    calls: tuple[AgentCall, ...]


class AgentReplay:
    """A `core.Agent` answering `act` with the recorded actions in order, starting over after
    the last; it logs every `act` and `learn`. An observation whose shape differs from the
    recording's raises `ValueError`."""

    def __init__(self, recording: AgentRecording) -> None:
        self.recording = recording
        self._acts = [c for c in recording.calls if c.call == "act"]
        self.acts: list[tuple[npt.NDArray[Any], bool]] = []
        self.learned: list[Transition] = []

    def act(self, obs: npt.NDArray[Any], *, explore: bool) -> npt.NDArray[Any]:
        call = self._acts[len(self.acts) % len(self._acts)]
        if call.obs is None or call.action is None or obs.shape != call.obs.shape:
            raise ValueError(f"obs: shape {obs.shape} is not the recording's")
        self.acts.append((obs, explore))
        return call.action.copy()

    def learn(self, t: Transition) -> None:
        self.learned.append(t)

    def save(self, path: Path) -> None:
        path.write_text(json.dumps({"player": self.recording.player}), encoding="utf-8")

    def load(self, path: Path) -> None:
        saved = json.loads(path.read_text(encoding="utf-8"))
        if saved != {"player": self.recording.player}:
            raise ValueError(f"{path}: not a checkpoint of {self.recording.player}")


@dataclass(frozen=True)
class RunWriterRecording:
    """A recorded run: its curve points, the teams checkpointed, the game count and the
    record `finish` returned."""

    points: tuple[CurvePoint, ...]
    checkpoints: tuple[str, ...]
    n_games: int
    record: RunRecord


class RunWriterReplay:
    """A `runs.RunWriter` that writes nothing: it logs each call in `calls`, checks that curve
    steps strictly increase, and `finish` returns the recorded `RunRecord` with that status."""

    def __init__(self, recording: RunWriterRecording) -> None:
        self.recording = recording
        self.calls: list[tuple[str, Any]] = []
        self.points: list[CurvePoint] = []

    def add_point(self, p: CurvePoint) -> None:
        if self.points and p.step <= self.points[-1].step:
            raise ValueError(f"curve: step {p.step} after {self.points[-1].step}")
        self.points.append(p)
        self.calls.append(("add_point", p))

    def save_checkpoint(self, agent: Agent, *, team: str = "agents") -> None:
        self.calls.append(("save_checkpoint", team))

    def save_generation(self, agent: Agent, *, team: str, index: int) -> Path:
        self.calls.append(("save_generation", (team, index)))
        return self.recording.record.path / "generations" / team / str(index)

    def save_games(self, games: Sequence[GameRecording]) -> None:
        self.calls.append(("save_games", len(games)))

    def finish(self, status: Literal["complete", "incomplete"]) -> RunRecord:
        self.calls.append(("finish", status))
        return replace(self.recording.record, status=status)


@dataclass(frozen=True)
class ReplayRecording:
    """A replayed game and the frame index each `advance` returned."""

    game: GameRecording
    advances: tuple[int, ...]


class ReplayDouble:
    """A headless `viz.Replay`: `advance` returns the recorded indices, then stays on the last
    frame; `show` advances to the end."""

    def __init__(self, recording: ReplayRecording, *, fps: float = 8.0) -> None:
        self.recording = recording
        self.fps = fps
        self.shown: list[int] = []

    def advance(self) -> int:
        recorded = self.recording.advances
        index = recorded[min(len(self.shown), len(recorded) - 1)]
        self.shown.append(index)
        return index

    def show(self) -> None:
        last = len(self.recording.game.frames) - 1
        while self.advance() < last:
            continue


def env_replay(symbol: str, case: str) -> EnvReplay:
    """The `core.Env` double of a recorded game, such as `("core.Env", "snake_wall_20")`."""
    return EnvReplay(sample(symbol, case, EnvRecording))


def agent_replay(symbol: str, case: str) -> AgentReplay:
    """The `core.Agent` double of a recorded player, such as `("core.Agent", "tabular_5")`."""
    return AgentReplay(sample(symbol, case, AgentRecording))


def run_writer_replay(case: str = "three_point_complete") -> RunWriterReplay:
    """The `runs.RunWriter` double of a recorded run."""
    return RunWriterReplay(sample("runs.RunWriter", case, RunWriterRecording))


def replay_double(case: str = "twelve_frames") -> ReplayDouble:
    """The `viz.Replay` double of a recorded replay."""
    return ReplayDouble(sample("viz.Replay", case, ReplayRecording))

